import useBuyerCatalogue from '../../sellers/useBuyerCatalogue';
import { DepartmentOffers, DeliveryEstimate } from '../../components/ShoppingBenefits';
import { DepartmentPhoto } from '../../components/DepartmentPhoto';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Search, ShoppingCart, Heart, X, Plus, Minus, Trash2, Package, ArrowLeft, SlidersHorizontal, Scale, Check, Download, MapPin, Share2, ArrowRight, Headphones, Grid2X2, List, Tag, User, Bell, Menu, ChevronRight, Truck, RotateCcw, CreditCard, MessageSquare, Pencil, Bookmark, CheckCircle2, Clock, Monitor, Keyboard, Camera } from 'lucide-react';
import { ELECTRONICS_PRODUCTS as suppliedProducts } from '../../data';
